UPDATE TB_POST_REPORT
   SET STATUS_CD = 'DISMISSED',
       ADMIN_NO  = #{adminNo}
 WHERE POST_ID = #{postId}
   AND STATUS_CD = 'PENDING'

UPDATE TB_POST
SET STATUS_CD = #{statusCd}


    , DELETE_DATE = SYSDATE


    , DELETE_DATE = NULL


WHERE POST_ID = #{postId}
  AND BOARD_TYPE IN ('TOWN', 'SHARE', 'LIFE')

UPDATE TB_MEMBER
SET ADMIN_POST_DEL_COUNT = NVL(ADMIN_POST_DEL_COUNT, 0) + 1
WHERE MEMBER_NO = #{memberNo}

UPDATE TB_MEMBER
SET ADMIN_COMMENT_DEL_COUNT = NVL(ADMIN_COMMENT_DEL_COUNT, 0) + 1
WHERE MEMBER_NO = #{memberNo}
